import net.minecraftforge.registries.RegistryObject;

public class AE2ClientPlugin {
    public static void onInit() {
    }

    public static void onRegister(IEventBus modEventBus, IEventBus gameEventBus) {
        modEventBus.addListener(AE2StorageModels::registerItemColors);
        modEventBus.addListener(AE2ClientPlugin::registerEntityRenderers);
    }

    public static void onCommonSetup() {
        OmniCraftingUnitType omniCraftingUnitType;
        ICraftingUnitType iCraftingUnitType;
        AE2StorageModels.registerStorageModels();
        for (RegistryObject<? extends OmniCraftingUnitBlock> registryObject : OCBlocks.CRAFTING_STORAGES) {
            iCraftingUnitType = ((OmniCraftingUnitBlock)registryObject.get()).type;
            if (iCraftingUnitType instanceof OmniCraftingUnitType) {
                omniCraftingUnitType = (OmniCraftingUnitType)iCraftingUnitType;
                BuiltInModelHooks.addBuiltInModel((ResourceLocation)AppEng.makeId((String)("block/crafting/" + registryObject.getId().m_135815_() + "_formed")), (UnbakedModel)new CraftingCubeModel((AbstractCraftingUnitModelProvider)new OmniCraftingUnitModelProvider(omniCraftingUnitType)));
            }
            ItemBlockRenderTypes.setRenderLayer((Block)((Block)registryObject.get()), (RenderType)RenderType.m_110463_());
        }
        for (RegistryObject<? extends OmniCraftingUnitBlock> registryObject : OCBlocks.CRAFTING_MONITORS) {
            iCraftingUnitType = ((CraftingMonitorBlock)registryObject.get()).type;
            if (iCraftingUnitType instanceof OmniCraftingUnitType) {
                omniCraftingUnitType = (OmniCraftingUnitType)iCraftingUnitType;
                BuiltInModelHooks.addBuiltInModel((ResourceLocation)AppEng.makeId((String)("block/crafting/" + registryObject.getId().m_135815_() + "_formed")), (UnbakedModel)new CraftingCubeModel((AbstractCraftingUnitModelProvider)new OmniCraftingUnitModelProvider(omniCraftingUnitType)));
            }
            ItemBlockRenderTypes.setRenderLayer((Block)((Block)registryObject.get()), (RenderType)RenderType.m_110463_());
        }
    }

    private static void registerEntityRenderers(EntityRenderersEvent.RegisterRenderers event) {
        event.registerBlockEntityRenderer(OCBlockEntities.OMNI_CRAFTING_MONITOR_BLOCK_ENTITY.get(), CraftingMonitorRenderer::new);
    }
}

